create table public.faqs (
  id uuid primary key default gen_random_uuid(),
  section text not null default 'general' check (section in ('cv','asesorias','general')),
  question text not null,
  answer text not null,           -- may contain {{precio:<product_id>}} and {{extra:<group_id>}}
  keywords text[] not null default '{}',
  show_on_page boolean not null default false,   -- also listed in the page's FAQ section
  active boolean not null default true,
  sort integer not null default 0,
  created_at timestamptz not null default now()
);
alter table public.faqs enable row level security;
create policy "faqs read" on public.faqs for select to anon, authenticated using (active or (select public.is_admin()));
create policy "faqs admin write" on public.faqs for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));

